const form = document.querySelector('#form-contato');
const nome = document.querySelector('#nome');
const email = document.querySelector('#email');
const corpo = document.querySelector('#corpo');
const resumo = document.querySelector('#resumo');

function atualizarResumo() {
  const nomeLimpo = nome.value.trim();
  const emailLimpo = email.value.trim();
  resumo.textContent =
    nomeLimpo || emailLimpo
      ? `Novo contato: ${nomeLimpo} <${emailLimpo}>`
      : '';
}

nome.addEventListener('input', atualizarResumo);
email.addEventListener('input', atualizarResumo);

form.addEventListener('submit', (evento) => {
  evento.preventDefault();

  const linha = document.createElement('tr');
  const celulaNome = document.createElement('td');
  celulaNome.textContent = nome.value.trim();
  const celulaEmail = document.createElement('td');
  celulaEmail.textContent = email.value.trim();

  linha.appendChild(celulaNome);
  linha.appendChild(celulaEmail);
  corpo.appendChild(linha);

  form.reset();
  atualizarResumo();
});
